children.nodeValue:
        body {
            font-family: 'Inter', sans-serif;
            margin: 0;
            padding: 0;
            background-color: #f8f9fa;
            color: #333;
        }

        /* Navbar */
        .navbar {
            background-color: #002855;
        }

        .navbar-brand {
            color: #fff;
            font-weight: 700;
            font-size: 1.6rem;
        }

        .navbar-nav .nav-link {
            color: #ddd;
            font-weight: 600;
        }

        .navbar-nav .nav-link:hover {
            color: #fff;
        }

        /* Hero Section */
        .hero {
            background: linear-gradient(to bottom, #003366, #002855), url('https://via.placeholder.com/1920x1080') center/cover no-repeat;
            color: #fff;
            padding: 5rem 1rem;
            text-align: center;
        }

        .hero h1 {
            font-size: 3rem;
            font-weight: 700;
            margin-bottom: 1.5rem;
        }

        .hero p {
            font-size: 1.25rem;
            margin-bottom: 2rem;
        }

        /* Info Boxes */
        .info-boxes {
            padding: 3rem 1rem;
            background-color: #fff;
        }

        .info-boxes h2 {
            text-align: center;
            font-size: 2rem;
            font-weight: 700;
            color: #004085;
            margin-bottom: 2rem;
        }

        .info-box {
            border: 1px solid #ddd;
            border-radius: 0.5rem;
            padding: 1.5rem;
            background: #f8f9fa;
            margin-bottom: 1.5rem;
            box-shadow: 0 2px 5px rgba(0, 0, 0, 0.1);
            transition: transform 0.3s ease, box-shadow 0.3s ease;
        }

        .info-box:hover {
            transform: translateY(-10px);
            box-shadow: 0 10px 20px rgba(0, 0, 0, 0.2);
        }

        .info-box h3 {
            font-size: 1.25rem;
            font-weight: 600;
            color: #004085;
        }

        .info-box p {
            font-size: 1rem;
            line-height: 1.6;
        }

        .info-box.warning {
            background-color: #fff3cd;
            border-left: 5px solid #ffc107;
            color: #856404;
        }

        /* Footer */
        .footer {
            background: linear-gradient(to bottom, #004085, #003366);
            color: #ccc;
            padding: 2rem 1rem;
            text-align: center;
        }

        .footer a {
            color: #ffd700;
            text-decoration: none;
            font-weight: 600;
        }

        .footer a:hover {
            text-decoration: underline;
        }

.justify-text {
    text-align: justify;
}
